using namespace std;

class Solution {
public:
    int minThreshold(vector<int>& nums, int k) {
        int n = nums.size();
        if ((long long)n * (n - 1) / 2 < k) return -1;
        int minV = *min_element(nums.begin(), nums.end());
        int maxV = *max_element(nums.begin(), nums.end());

        auto countPairs = [&](int thresh) {
            long long cnt = 0;
            for (int i = 0; i < n; ++i) {
                for (int j = i + 1; j < n; ++j) {
                    if (nums[i] > nums[j] && nums[i] - nums[j] <= thresh) {
                        cnt++;
                    }
                }
            }
            return cnt;
        };

        int l = 0, r = maxV - minV;
        int ans = -1;
        while (l <= r) {
            int mid = l + (r - l) / 2;
            if (countPairs(mid) >= k) {
                ans = mid;
                r = mid - 1;
            } else {
                l = mid + 1;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int minThreshold(int[] nums, int k) {
        int n = nums.length;
        if ((long) n * (n - 1) / 2 < k) return -1;
        int minV = nums[0], maxV = nums[0];
        for (int v : nums) {
            if (v < minV) minV = v;
            if (v > maxV) maxV = v;
        }

        int l = 0, r = maxV - minV;
        int ans = -1;
        while (l <= r) {
            int mid = l + (r - l) / 2;
            if (countPairs(nums, mid) >= k) {
                ans = mid;
                r = mid - 1;
            } else {
                l = mid + 1;
            }
        }
        return ans;
    }

    private long countPairs(int[] nums, int thresh) {
        long cnt = 0;
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (nums[i] > nums[j] && nums[i] - nums[j] <= thresh) {
                    cnt++;
                }
            }
        }
        return cnt;
    }
}

var minThreshold = function(nums, k) {
    const n = nums.length;
    if ((n * (n - 1)) / 2 < k) return -1;
    let minV = nums[0], maxV = nums[0];
    for (const v of nums) {
        if (v < minV) minV = v;
        if (v > maxV) maxV = v;
    }

    const countPairs = thresh => {
        let cnt = 0;
        for (let i = 0; i < n; i++) {
            for (let j = i + 1; j < n; j++) {
                if (nums[i] > nums[j] && nums[i] - nums[j] <= thresh) {
                    cnt++;
                }
            }
        }
        return cnt;
    };

    let l = 0, r = maxV - minV;
    let ans = -1;
    while (l <= r) {
        const mid = Math.floor((l + r) / 2);
        if (countPairs(mid) >= k) {
            ans = mid;
            r = mid - 1;
        } else {
            l = mid + 1;
        }
    }
    return ans;
};
